/// Single-player: 10 worlds × 10 stages (docs/GAME_DESIGN_V2.md §7).
/// Stage n recommends Lv n; the CPU fights at Lv n with its stats scaled by
/// the stage's position in the world ([kStagePowerPct]); AI tier by stage.
/// CPU doodles are the bundled ones (`app/assets/cpu/manifest_v2.json`).
library;

import 'ai.dart';
import 'stage_power_table.dart';

export 'stage_power_table.dart';

/// The design's CPU stat scale by position in a world (88 … 98 % boss,
/// GAME_DESIGN_V2 §7) — the starting point of the per-stage tuning. The
/// shipped values are [kStagePowerTable] (generated by
/// `dart run tool/v3_sim.dart tune-stages`): each stage's real CPU doodle,
/// level and AI tier tuned to the design's win curve (docs/BATTLE_V3.md).
const List<int> kStagePowerPct = [88, 89, 90, 91, 92, 93, 94, 95, 96, 98];

const List<String> kWorldNames = [
  'らくがき のはら',
  'クレヨン もり',
  'えのぐ うみ',
  'いろえんぴつ やま',
  'ペンギン こおり',
  'マーカー まち',
  'ねんど さばく',
  'はさみ おしろ',
  'にじいろ そら',
  'まっしろ ノート',
];

/// CPU doodles per world: the first entries rotate through stages 1–9, the
/// last one is the world's boss (stage 10, shown big).
const List<List<String>> kWorldRosters = [
  ['cpu_fire_blob', 'cpu_leaf_caterpillar', 'cpu_stickman', 'cpu_leaf_frog'],
  ['cpu_bear', 'cpu_butterfly', 'cpu_hedgehog', 'cpu_thunder_bird'],
  ['cpu_water_fish', 'cpu_octopus', 'cpu_jellyfish', 'cpu_swordfish'],
  ['cpu_rock_golem', 'cpu_flower', 'cpu_fire_spiky', 'cpu_dino'],
  ['cpu_penguin', 'cpu_snowman', 'cpu_water_snake', 'cpu_shadow_ghost'],
  ['cpu_car', 'cpu_train', 'cpu_rainbow_robot', 'cpu_ufo'],
  ['cpu_crab', 'cpu_cactus', 'cpu_thunder_star', 'cpu_shadow_bat'],
  ['cpu_knight', 'cpu_rainbow_cat', 'cpu_rocket', 'cpu_castle'],
  ['cpu_cloud', 'cpu_rainbow_bird', 'cpu_kite', 'cpu_dragon'],
  ['cpu_stickman', 'cpu_knight', 'cpu_dragon', 'cpu_scribble_king'],
];

/// One single-player stage.
class Stage {
  const Stage({
    required this.stage,
    required this.world,
    required this.position,
    required this.recommendedLevel,
    required this.cpuLevel,
    required this.tier,
    required this.cpuId,
    required this.boss,
    required this.cpuPowerPct,
  });

  /// 1..100.
  final int stage;

  /// 1..10.
  final int world;

  /// 1..10 within the world (10 = boss).
  final int position;
  final int recommendedLevel;
  final int cpuLevel;
  final AiTier tier;

  /// Bundled CPU doodle id (`manifest_v2.json`).
  final String cpuId;
  final bool boss;

  /// CPU stats are scaled by this % (difficulty within a world).
  final int cpuPowerPct;

  String get worldName => kWorldNames[world - 1];

  Map<String, Object?> toJson() => {
    'stage': stage,
    'world': world,
    'position': position,
    'recommendedLevel': recommendedLevel,
    'cpuLevel': cpuLevel,
    'aiTier': tier.name,
    'cpuId': cpuId,
    'boss': boss,
    'cpuPowerPct': cpuPowerPct,
  };
}

/// AI tier of stage [n]: 1–20 よわい, 21–60 ふつう, 61–100 つよい.
AiTier stageTier(int n) =>
    n <= 20 ? AiTier.weak : (n <= 60 ? AiTier.normal : AiTier.strong);

/// The 100 stages.
List<Stage> stageTable() => [for (var n = 1; n <= 100; n++) stageAt(n)];

/// Stage [n] (1..100).
Stage stageAt(int n) {
  final world = (n - 1) ~/ 10 + 1;
  final pos = (n - 1) % 10 + 1;
  final roster = kWorldRosters[world - 1];
  final boss = pos == 10;
  final tier = stageTier(n);
  return Stage(
    stage: n,
    world: world,
    position: pos,
    recommendedLevel: n,
    cpuLevel: n,
    tier: tier,
    cpuId: boss ? roster.last : roster[(pos - 1) % (roster.length - 1)],
    boss: boss,
    cpuPowerPct: kStagePowerTable[n - 1],
  );
}
